class CallableMock
{
public:
	mem_unique_ptr<Object> obj;
	void function1(Variant arg0)
	{
		function1_calls++;
		function1_latest_arg0 = arg0;
	}

	unsigned function1_calls{0};
	Variant function1_latest_arg0;
};

