	texture_rect->set_expand_mode(TextureRect::EXPAND_FIT_WIDTH);
	CHECK(texture_rect->get_expand_mode() == TextureRect::EXPAND_FIT_WIDTH);

	texture_rect->set_expand_mode(TextureRect::EXPAND_FIT_WIDTH_PROPORTIONAL);
