	const char *wk_sig_sha256 = "3046022100a1b768db040dea7a79c81f10fd0b3d34d53fe941cdd46ee1a382ce27310a9826022100c038ce88b59ff6f9fbe7837f0ff5e5079adf7995ac2d86e2baf03bfa1cda5cd4";

